∀ {n : Nat} {G : SimpleGraph.{0} (Fin n)} {dartCount : Nat} {tail : Fin dartCount → Fin n}
  {reverse : Equiv.Perm.{1} (Fin dartCount)}
  {reverse_involution : ∀ (d : Fin dartCount), Eq.{1} (reverse (reverse d)) d}
  {reverse_fixedpoint_free : ∀ (d : Fin dartCount), Ne.{1} (reverse d) d}
  {dart_adjacent : ∀ (d : Fin dartCount), SimpleGraph.Adj.{0} G (tail d) (tail (reverse d))}
  {dart_injective : Function.Injective.{1, 1} fun d => Prod.mk.{0, 0} (tail d) (tail (reverse d))}
  {dart_surjective :
    ∀ (u v : Fin n), SimpleGraph.Adj.{0} G u v → ∃ d, And (Eq.{1} (tail d) u) (Eq.{1} (tail (reverse d)) v)}
  {connected : SimpleGraph.Connected.{0} G} {vertex_nonempty : ∀ (v : Fin n), ∃ d, Eq.{1} (tail d) v}
  {rotate : Equiv.Perm.{1} (Fin dartCount)} {rotate_tail : ∀ (d : Fin dartCount), Eq.{1} (tail (rotate d)) (tail d)}
  {vertex_cyclic : ∀ (d e : Fin dartCount), Eq.{1} (tail d) (tail e) → Equiv.Perm.SameCycle.{0} rotate d e}
  {dartCount_1 : Nat} {tail_1 : Fin dartCount_1 → Fin n} {reverse_1 : Equiv.Perm.{1} (Fin dartCount_1)}
  {reverse_involution_1 : ∀ (d : Fin dartCount_1), Eq.{1} (reverse_1 (reverse_1 d)) d}
  {reverse_fixedpoint_free_1 : ∀ (d : Fin dartCount_1), Ne.{1} (reverse_1 d) d}
  {dart_adjacent_1 : ∀ (d : Fin dartCount_1), SimpleGraph.Adj.{0} G (tail_1 d) (tail_1 (reverse_1 d))}
  {dart_injective_1 : Function.Injective.{1, 1} fun d => Prod.mk.{0, 0} (tail_1 d) (tail_1 (reverse_1 d))}
  {dart_surjective_1 :
    ∀ (u v : Fin n), SimpleGraph.Adj.{0} G u v → ∃ d, And (Eq.{1} (tail_1 d) u) (Eq.{1} (tail_1 (reverse_1 d)) v)}
  {connected_1 : SimpleGraph.Connected.{0} G} {vertex_nonempty_1 : ∀ (v : Fin n), ∃ d, Eq.{1} (tail_1 d) v}
  {rotate_1 : Equiv.Perm.{1} (Fin dartCount_1)}
  {rotate_tail_1 : ∀ (d : Fin dartCount_1), Eq.{1} (tail_1 (rotate_1 d)) (tail_1 d)}
  {vertex_cyclic_1 : ∀ (d e : Fin dartCount_1), Eq.{1} (tail_1 d) (tail_1 e) → Equiv.Perm.SameCycle.{0} rotate_1 d e},
  Eq.{1}
      { dartCount := dartCount, tail := tail, reverse := reverse, reverse_involution := reverse_involution,
        reverse_fixedpoint_free := reverse_fixedpoint_free, dart_adjacent := dart_adjacent,
        dart_injective := dart_injective, dart_surjective := dart_surjective, connected := connected,
        vertex_nonempty := vertex_nonempty, rotate := rotate, rotate_tail := rotate_tail,
        vertex_cyclic := vertex_cyclic }
      { dartCount := dartCount_1, tail := tail_1, reverse := reverse_1, reverse_involution := reverse_involution_1,
        reverse_fixedpoint_free := reverse_fixedpoint_free_1, dart_adjacent := dart_adjacent_1,
        dart_injective := dart_injective_1, dart_surjective := dart_surjective_1, connected := connected_1,
        vertex_nonempty := vertex_nonempty_1, rotate := rotate_1, rotate_tail := rotate_tail_1,
        vertex_cyclic := vertex_cyclic_1 } →
    And (Eq.{1} dartCount dartCount_1)
      (And (HEq.{1} tail tail_1) (And (HEq.{1} reverse reverse_1) (HEq.{1} rotate rotate_1)))

∀ {V : Type u_1} {graph : SimpleGraph.{u_1} V} {adjacency : Matrix.{u_1, u_1, 0} V V Real}
  {symmetric : ∀ (i j : V), Eq.{1} (adjacency i j) (adjacency j i)}
  {edge_sign :
    ∀ (i j : V), SimpleGraph.Adj.{u_1} graph i j → Or (Eq.{1} (adjacency i j) 1) (Eq.{1} (adjacency i j) (-1))}
  {nonedge_zero : ∀ (i j : V), Not (SimpleGraph.Adj.{u_1} graph i j) → Eq.{1} (adjacency i j) 0}
  {graph_1 : SimpleGraph.{u_1} V} {adjacency_1 : Matrix.{u_1, u_1, 0} V V Real}
  {symmetric_1 : ∀ (i j : V), Eq.{1} (adjacency_1 i j) (adjacency_1 j i)}
  {edge_sign_1 :
    ∀ (i j : V), SimpleGraph.Adj.{u_1} graph_1 i j → Or (Eq.{1} (adjacency_1 i j) 1) (Eq.{1} (adjacency_1 i j) (-1))}
  {nonedge_zero_1 : ∀ (i j : V), Not (SimpleGraph.Adj.{u_1} graph_1 i j) → Eq.{1} (adjacency_1 i j) 0},
  Eq.{u_1 + 1} (Conjecture2161.SignedGraph.mk.{u_1} graph adjacency symmetric edge_sign nonedge_zero)
      (Conjecture2161.SignedGraph.mk.{u_1} graph_1 adjacency_1 symmetric_1 edge_sign_1 nonedge_zero_1) →
    And (Eq.{u_1 + 1} graph graph_1) (Eq.{u_1 + 1} adjacency adjacency_1)

